const LayoutTerrain *world_terrain_team(const char *name)
{
    for(size_t i=0;i<sizeof(terrains)/sizeof(*terrains);++i)
        if(strcmp(name,terrains[i].name)==0)return &terrains[i].terrain;
    return NULL;
}
